script:
frappe.ui.form.on('Validation Exception', {
    refresh: function(frm) {
        frm.add_custom_button('View Summary', function() {
            frappe.call({
                method: 'veriflow.veriflow.api.get_exception_summary',
                callback: function(response) {
                    let data = response.message;

                    let status_rows = data.by_status.map(
                        row => `<tr><td>${row.status}</td><td>${row.count}</td></tr>`
                    ).join('');

                    let severity_rows = data.by_severity.map(
                        row => `<tr><td>${row.severity}</td><td>${row.count}</td></tr>`
                    ).join('');

                    let html = `
                        <p><strong>Total Exceptions:</strong> ${data.total}</p>
                        <h5>By Status</h5>
                        <table class="table table-bordered">
                            <tr><th>Status</th><th>Count</th></tr>
                            ${status_rows}
                        </table>
                        <h5>By Severity</h5>
                        <table class="table table-bordered">
                            <tr><th>Severity</th><th>Count</th></tr>
                            ${severity_rows}
                        </table>
                    `;

                    let dialog = new frappe.ui.Dialog({
                        title: 'Exception Summary',
                        fields: [
                            {
                                fieldtype: 'HTML',
                                fieldname: 'summary_html',
                                options: html
                            }
                        ]
                    });

                    dialog.show();
                }
            });
        });

        frm.add_custom_button('Go to Veriflow Workspace', function() {
            frappe.set_route('veriflow');
        });
    }
});

frappe.listview_settings['Merchant Record'] = {
    onload: function(listview) {
        listview.page.add_inner_button('Run Rule Engine', function() {
            frappe.call({
                method: 'veriflow.veriflow.rule_engine.evaluate_all_records',
                freeze: true,
                freeze_message: 'Checking all Merchant Records against active rules...',
                callback: function(response) {
                    let count = response.message;
                    frappe.show_alert({
                        message: `Rule engine complete — ${count} new exception(s) created.`,
                        indicator: count > 0 ? 'orange' : 'green'
                    });
                    listview.refresh();
                }
            });
        });
    }
};
